	FOREIGN KEY(workspace_id) REFERENCES workspaces (id)
);

CREATE TABLE release_decisions (
	release_id VARCHAR(36) NOT NULL,
	verdict VARCHAR(30) NOT NULL,
	reasons JSON NOT NULL,
	evidence JSON NOT NULL,
